
/*
Adding a single record */
-- @block
INSERT IGNORE INTO surnames(isibongo,izithakazelo,umlando,well_known_people, images) VALUES
    ('cele',
    'Ndosi, Magaye, Nkomo isengwa ilele Nkomo kayivuswa, Khumbuza, Siqunga esihle esingahlalwa nyoni. Mkhokheli owakhokhela isizwe ekugqilazweni. Dubandlela, Magaye ongangolwandle.',
    'Abantu bakwaCele bangaMalala Nguni ngokwezigaba zabaNguni. Lesi sibongo sakwaCele siphuma kwesakwaMthethwa. Ukhokho wabantu bakwaCele nguMadango kaNdunakazi kaMthethwa kaNyambose kaKhubazi. UMadango endlunkulu wazala uXaba owazala uKhayi owazala uJobe owazala uGodongwana (inkosi uDingiswayo). Ekhohlo uMadango wazala uCele owazala uLugogo owazala uNdosi owazala uMaganga owazala unqumela owazala uLanga owazala uMkhokheli owazala uDubandlela. Inkosi uDubandlela yayakhe umuzi wayo endaweni osekuyi Groutville manje. Ngesikhathi sokubusa kwenkosi uDingiswayo kwaMthethwa kwaCele kwakubusa yona inkosi uDubandlela. Inkosi uDubandlela yaphila isikhathi eside ngendlela eyisimanga angangokuthi amadodana ayo okwakufanele athathe ubukhosi emva kwayo aze ashona kwawona. Endala kwakunguMdinsilwa owashona nendodana yakhe bengabusanga. Encane kaakunguVico, naye washona uyise esawadla anhlamvana. Kwase kuthi amadodana kaVico, oMande noMagaye, bathathelana izikhali babanga ubukhosi uyisemkhulu esaphila. Ekubangeni kwabazukulu benkosi uDubandlela nguMagaye owadla umhlanganiso. UMagaye washiya emzini kayisemkhulu wayokwakha umuzi wakhe emthonjeni womfula uMhlali, kwathi umfowabo uMande wawela umfula uMvoti wazokwakha lapho sekuyidolobha lakwaDukuza khona. \n Kwathi lezi zinsizwa zisazihlalele emizini yazo wafika izithunywa zivela eSilweni uShaka, saqale saya kuMande, sathi, ithi iNgonyama impi yayo ilambile ifuna ukuba ithole ukudla ukuze ithole amandla okulwa. UMande wakhomba inja endala ezacile wathi kabathathe yona bayokudla. Lezo zithunywa zedlulela kuMagaye zafika zasho umlayezo ofanayo, yena waziphatha kahle wazihlabisa nokuzihlabisa,wethembisa nokuthi uzozinekeza konke ezikufunayo. ILembe layizwa indelelo kaMande lathukuthela lathelwa ngamanzi. UMande wafunda kwezakhe washeshe wabaleka nabantu bakhe bashiya yonke imfuyo yabo esitheni. Babaleka bayocasha ngasolwandle. ILembe lathi makangalandelwa kodwa makancishwe ukudla. Yabhoka indlala kangangokuthi uMande waze wacela umfowabo uMagaye owayehlezi ngokunethezeka neSilo uShaka ukuba makayomncengela kuso. Ngempela uMagaye wamncengela umfwabo eNgonyameni yakwaZulu. Yavuma yathi makaphume ekubhaceni abuyele emzini wakhe. Kwathu lapho esazihlalele enethezekile zaphinde zaqhumuka futhi leziya zithunywa zeLembe. Kulokhu zafike zathi ithi iNgonyama sizobamba leya nja ezacile siyibulala sidle. Ngempela zazizobika ukuthi uMande makazilungiselele impi ngoba wayezohlaselwa kungekudala. Wafunda kwezakhe futhi uMande wabaleka, wavele wanyamalala. Kwase kuthi iLembe lavele lazikhokhisela ngokuthi livele lakhe umuzi walo wakwa Dukza emanxiweni kaMande. Lowo muzi yiwo osulidolobha manje. Kwathi lapho iSilo uShaka sesikhotheme sekubuza iSilo uDingane, iSilo uDingana saqala umkhankaso waso wokubulala bonke ababengabangane beLembe. UMagaye naye wabulawa. Esekhotheme uMgengi sekubusa iSilo uDingane waqhamuka futhi uMande. Kuthe lapho esahleli ejabulele nanokuthi isitha sakhe asisekho kwaqhamuka uNqetho Qwabe wahlasela uMande. Bahlakazeka abantu bakwaCele bagcwala lonke elakwaZulu.',
    '["Amahle Cele, South African Artist", " Henry Cele, Football Player & Actor", " Baby Cele, Actor"]', '["images/Baby_Cele.jpeg"]')


/*
Adding a group of records*/

-- @block
INSERT IGNORE INTO surnames(isibongo, izithakazelo, umlando, well_known_people) VALUES
('khumalo',
 'Mntungwa Mbulaz''omnyama Nina bakaBhej'' eseNgome Nin'' enadl''umuntu nimyenga ngendaba Zindlovu ezibantu, Zindlovu ezimacocombela',
 'AbakwaKhumalo Njengoba abaNguni behlukaniswe izigaba ezinhlanu, kukhona abaNguni baseMbo, abaNguni baseButhonga, aMaNtungwa Nguni, AMaLala noma AmaNhlenga Nguni, kanye namaMaDebe Nguni. AbakwaKhumalo bawela esigabeni saMaNtungwa Nguni, baphinde baziwe ngokuthi bangaMantungwa (hhayi isigaba sobuNguni) ngoba bezalwa nguMntungwa indodana kaMbulazi kaNdabezitha kaMmusi. UMbulazi wayenamadodana amabili, okwakunguMntungwa kanye nomnewabo uMabaso(owesibongo)',
 '["Leleti Khumalo, South African Actress", "Dr Khumalo, South African Football Player", "Alf Khumalo, South African Photographer"]'),

('dladla',
 'Ndabezitha, Mgabadeli, Owagabadel''inkundla yakwaBulawayo. Gadlela, Dwala, Mpembe, Mhlophe, Vezi, Dladla, Nyazitha Magalel''agoqe njengeshongololo!!',
 'AbakwaDladla bangabantu baseMambatheni. Isibongo sakwaDladla savela ngoDladla '' indodana kaNdaba kaSontshikazi kaMphangazitha(Phangizitha) kaMageba kaZulu kaMalandela kaLuzumane kaMnguni kaGumede. Uyise kaDladla uNdaba wayenamadodana amathathu, uMbeje (inkosana yomndeni), uDladla (owelama uMbeje), kanye noShandu (owayemncane).Ukwelamana kwabakwa Dladla. UDladla wazala uMpembe, uMgabadeli, uMhlophe, uGadlela kanye noDwala. UMgabadeli wazala ukweyama kanye noMathenjwa. UMhlophe wazala uNonjiko noKolotshana. UKweyama wazala uVezi owazala uMnembe.UNonjiko kaMhlophe wazala uNoshevu noJobha. UJobha wazala uNolenge. UNoshevu wazala uMadanyini, uNgobeza, uNkenke, uLukhoso kanye noGxaza. UGxaza wazala uNompontshela, uMzongolozi, uMxhayi nabanye. UNompontshela wazala uMuzikayifani, uMkhululi, uBonginkosi nabanye. UMgabadeli kwabe kuyindodana ka Dladla. Kuthiwa uMgabadeli lona wazuza lezibongo zakhe ezithi `Wena owagabadela inkundla yakwaBualwayo` ngoba naye wayeyinyanga enkulu ngesikhathi kusabusa iLembe. Kuthiwa waba ngomunye walezangoma ezanuka lona kanye iLembe ngesenzo salo sokugcoba izindlu zesigodlo ngegazi.',
 '["Pallance Dladla, South African Actor", "Khaya Dladla, South African Actor", "Anele Dladla aka Dladla Mshunqisi, South African Musician", "Nelson Teenage Dladla, Former South African Football Player"]'),

('dlamini',
 'Dlamini, Sibalukhulu Lusibalukhulu, Machoboza umhlanga kuvele indlela, Wena waseQhudeni, Mfazi omabele made oncelisa ingane ngaphesheya komfula, Mvingaze, Masebsebe, Mdlovu, Nkomo zidl''ekhaya ngokweswela abelusi, Sgayela, Maduzela, Nombanga ka Lokothwayo, Wena KaMevana, Mdineka, Bhulingwe, Mazongwe, Sivunga ka Dlomo, Nomagama, Khukhulela ka Mmiso, Inkosi kayiqedwa.',
 'Abantu bakwaDlamini bangabaNguni baseMbo ngokwezibanga zabaNguni . Njengokuchaza kwethu ngokwedlule ngenkanthi sichaza indlu yenkosi uNyanya, isibongo sakwaDlamini sikhulu kakhulu kangokuthi abantu bakwaDlamini baze baphikane bethi abahlobene,ngenxa yokuhluka kwezithakazelo nezithopho . Ziningi izindlu kwaDlamini. Ezinye zalezo zindlu sezaba yizibongo , kanti futhi kwaDlamini kuphuma izibongo eziningi kakhulu . Njengokuchaza kwethu ngokwedlule , isibongo sakwaDlamini siphuma eSwazini , sisekanye nalaba oDlamini ababusa eSwazini abazibiza ngokuthi bangaMalangeni , ababuzwa yiNgwenyama uMswati wesithathu . Lesi sibongo sakwaDlamini sisukela kuDlamini wokuqala okuthiwa wayezalwa nguCebisa ka Ngwane wokuqala . Kuhambe kwahamba enye ingxenye yakwaDlamini yagcina isithelwe eSwazini, yaphelele lapho sekukwaZulu -Natali khona namuhla. Kuthiwa leyo ngxenye yayiholwa nguMnyambane owazala uKutha , yena owazala uNomagwala . Kuleyo ngxenye kwagcina sekuphuma nezindlu eziningi ,esingabala iNdlu yeNkosi uNyanya , iNdlu yaseMakhuzeni, iNdlu yaseNhlangwini , iNdlu yakwaMntwana kanye nezinye izindlu . INdlu yaseMakhuzeni ingenye yeziNdlu zenkosi uDlamini wesibili.\n\nINdlu yaseMakhuzeni igqamisa kakhulu  uLusibalukhulu\\uSibalukhulu, ezithakazelweni zayo . uSibalukhulu lona ungukhokho wabo abaseMakhuzeni, wabe eyinkosi yabo. Kuthiwa inkosi uSibalukhulu\\uLusibalukhulu yayizalwa uDlomo ka Nhlonhlonde ka Lubiyelo ka Lolwa ka Lokothwayo {kukhona oDlamini abathakazela ngoLokothwayo , Mntungwa njalo njalo }, ka Siqgongweni ka Nomagwala . Kuthiwa inkosi  uLusibalukhulu yazala oDlamini wesibili noLuthuli. Kuthiwa uDlamini , owabe eyinkosana,nguyena owalandela uyise esihlalweni sobukhosi. Inkosi uDlamini wesibili  yazala uMdineka {eMakhuzeni}, yabuye yazala noBuhlabudze {kwaBhidlala}yabuye yazala noMakhatha {eNhlangwini}, kanye nezinye izinsizwa . UMdineka kuthiwa nguyena owabe eyinkosana yaseMakhuzeni . Wayezalwa uNdlunkulu wenkosi uDlamini wesibili  uMaNyinde . Ngesikhathi sokubusa kweLembe, iSilo uShaka, le Ndlu yaseMakhuzeni yayizinze ngaseLenge , ibuswa inkosi yayo uMmiso ka Mazongwe. Kwathi ngenkanthi inkosi yaseBathenjini uNgoza ibalekela ulaka lweLwembe iphikelela eNingizimu, abaseMakhuzeni nabo bazibandakanya nayo inkosi uNgoza , baphikelela eMampondweni kanye nenNkosi uNgoza eyagcina ikhothemele khona kwelaMampondo. Kwathi lapho iLembe selikhotheme ngo1828, inkosi uMmiso yayiphindela kwelakwaZulu , kanti iyofika ibulawe yiSilo uDingane esaselibusa ngalelo sikhathi. Kuthiwa impi yeSilo uDingane yayibulalela ngasoThukela inkosi uMmiso. Kwathi indodana yenkosi uMmiso{eyabe isencane ngaleso sikhathi} ogama layo kwakunguKhukhulela , yathathwa yayiswa enkosini uFodo inkosi yaseNhlangwini, okuyilapho yakhulela khona . Yathi ingakhula yayubuyela emuva yayothatha ubukhosi bukaYise eMakhuzeni. Inkosi uKhukhulela yazala uMsikhoni, uMadulwini, uPhatha, uCwi, uFidi . UMsikhoni nguyena owabe eyinkosana yenkosi uKhukhulela, nguyena owabusa ngemva kokukhothama kukaYise . Yena wazala inkosi Mehlokazulu , yona yazala inkosi uLesimane , inkosi uLesimane yazala uMlindeli',
 '["Minnie Dlamini, South African Media Personality", "Amala Dlamini, Artist"]'),

('ndlovu',
 'Gatsheni, Boya benyathi, obusonga busombuluka. Mpongo kaZingelwayo. Ngonyama, Nina bakwaNdlovuzidl''ekhaya, ngokweswel''abelusi, Zaze zeluswa intombi uDemazane, Nina bakwaKhumbul''amagwala, Nina bakwaDemazane Ntombazane, Nina bakwaS''hlangu sihle, Mthiyane! Ngokuthiy''amadoda emazibukweni, Nina bakwaMdubusi.',
 'Umlando ngesibongo sakwaNdlovu Abantu bangabeSuthu badabuka eLesotho.Ekufikeni kwabo kwelakwaZulu bafike bakhonza esizweni sabantu bakwaNxamalala.Laba bantu bakwaNdlovu bangabantu bakaMatsimane wakwaTlou noma uMotaung.Kuthiwa abantu ababekhuluma ulimi lwesiZulu behluleka ukuphimisa igama noma ngithi isibongo esithi Tlou,bagcina bethe Ndlovu.Ngenkathi laba bantu bakwaNdlovu bakhe laphaya eNkandla, babeyingxenye yezizwe saMachunu.Laba bantu bakwaNdlovu babakhelene nabantu bakaMavovo wakwaMkhize phezu komfula iNsuze ngaphansi kwaseQhudeni eNkandla.Baxoshwa esizweni saMaChunu ngoba enye yabazukulu bakaGatsheni uMpongo kaZingelwayo esolwe ngokuthakathiwa.Kuthiwa wayefuye izinyoni ezimbili ezicishe zifane nokhozi.Babaleka abantu bakwaNdlovu bayokhonza kuZihlandlo wakwaMkhize bebalekela ulaka lukaMacingwane.Kuthe lapho besathi benethezekile kwasuka inkosi yakwaZulu uMbomboshe omnyama[uDinngane kaSenzangakhona]wahlasela uZihlandlo wambulala.AbakwaNdlovu behlangene nabakwaMkhize babeleka balibhekisa ngaseNingizimu,baze bayofika eqqumaneni laseNhlazuka eduze nomfula iLovu.Ngaleso sikhathi abantu bakwaNdlovu basebeholwa nguNgema indodana kaMpongo.UNgema yena wazala uNogwiyela,yena wazala uMdingiuMdingi yena wasuka eNhlazuka wayokwakha eMngeni.Ngokuhlaselwa kwabo nguMacingwane baze bayokhonza kuZihlandlo,bazibona bengasenaboya.Nangokuhlaselwa kukaZihlandlo nguDingane kanti nguyena obese bafukamele babona ukuthi uboya babo obungamandla abo,bazibiza ngokuthi ngabakwaBoyabenyathi ,obuthi busomanqoba busombuluka.',
 '["Duma Ndlovu, South African Filmmaker"]'),

('ngcobo',
 'Mapholoba, Nyuswa, Fuze, Mavela, Mafuz''afulele njengefu lemvula, Mashiya amahle ngath'' azoshumayela, Dambuza, Mthabathe, Mabhala ngozipho abanye bebhala ngepensela, Malal''efake umunwe endunu, Avuke ekuseni awuncinde akhombe ilanga, Mavulankungu kuvel''ilanga, Sididane, Ngongoma, Maqadi amakhulu, Mbili!',
 'Abantu bakwaNgcobo bangaMalala avela eNyakatho nezwe. Abantu bakwaNgcobo sibathola beneNdlunkulu, iQadi kanye neKhohlwa kuze kufike nakwisizinda. Ukuze uchazeke kahle umlando wakwaNgcobo kumele uchazwe ngezindlu. Kuthiwa umuntu wokuqala owaba yinzalabantu, simthola akhe umuzi wakhe eduze komfula uThukela, ezansi nalo. Igama lakhe kuthiwa nguVumezitha. UVumezitha wazala amadodana amaningi, kodwa engizowabalula lapha ayezalwa ngunina oyedwa kwaba nguNgcobo kanye noMkheshana. Izibongo ezithinte oNgcobo zivela kulaba bantu ababili, abangamadodana kaVumezitha. Ukuze izinto zihambe kahle kufanele sizicaze kahle izindlu zakwaNgcobo, kusukela endlunkulu yakhona size sifike endlini encane. Lena yindlu enkulu yakwaNgcobo, yaziwa ngokuthi yiNkumbemfece. Lokhu kuvela kwenye yamadoda akwaNyuswa. Abantu bakwaNyuswa kuthiwa babakhe eduze komfula obizwa ngokuthi iMamba, ongumngenela woThukela njengoba inzalabantu yakwaNgcobo yayakhe eduze koThukela. Indlu yakwaNyuswa isukela kuVumezitha ugobo, ozale uNgcobo kanye nomnawakhe uMkheshane. UNgcobo yena uzale uDingile, Dingile uzale amadodana amabili, oNyuswa kanye noZonca. UNyiswa yena uzale Yenesi, kwathi uZonca yena wazala Maguya. Kuthiwa Yenesi katholanga ndlalifa, kwase kuthi Maguya wasendlini encane wangena umkaYenesi ukuze amzalele indlalifa. Nempela wazala uMbhele, yena wazala uMapholoba wodumo lwakwaNgcobo. UMapholoba uzale amadodana amathathu oSihayo (inkosana), moMvelaikhohlwa), kanye noMgabi. Lawa kwakungamadodana kaMapholoba, ngezindlu zawo. USihayo uzale uDubuyana yena wazala uDeliweyo, yena wazala uMqedi namnye amakhosi. Kanti Mavela uzale amadodana amabili uMkhalelwa kanye noSindila. UMkhalelwa yena uzale uDikwayo yena wazala uSotobe. Kanti uMgabi, yena uzale uNcume, yena wazala amadodana amabili oMshiswa noMnkwantshi. Ngesikhathi sokubusa kukaShaka kwaZulu, kwaNyuswa kwakubusa Mapholoba. Bathi noma izinsuku zase zihambile, insizwa endala yayingayishiyi edlamabele. Ngoba phela Mapholoba simthola esaganwa ngudadewabo kaZihlandlo waseMbo (kwaMkhize). Kodwa okubi okwenziwa Mapholoba ukuqhatha amadodana akhe Sihayo noMgabi ethi kababange ubukhosi. Nempela babanga ngesikhathi esengasekho uyise. Izindlu zonke zavuma Sihayo njengenkosana. Wasuka lo mbango waba mkhulu waze walanyulwa nguShaka ewulamula ngenja. Kuthiwa iLembe lo mango lawulamula ngokuhlanganisa abantu lathi babenze umkhumbi wabantu, amadodana kaMapholoba nawo abakhona kulo mkhumbi. UShaka weza nenja yakhe, eyahamba nomkhumbi wabantu ihamba ibanuka. Kuthiwa yabanuka bonke abantu kodwa yathi lapha ifika kuSihayo ayaze yamnuka, yasuke yalala phansi eduze kwakhe. Lesi senzo senja Shaka washumusha ngokuthi ayimnukanga Sihayo ngoba kunguyena inkosi. Kanti kuzothi emva kwesikhathi uMgabi aqhathe Sihayo noShaka ngokuqamba amanga okuthi Sihayo uthumelele Shaka ugwayi unomuthi ukuze uShaka ethi uyawubhema akhothame. UShaka wakuzwa lokho ahlasela elakwaNyuswa. Wayezoshaya aqothe imbokodo nesisekelo ukba umhlobo wakhe uZihlandlo wakwaMkhize kabafihlanga kuye abanye abantu bakwaNyuswa. Laba bantu bakwaNyuswa bahlala kwaze kwathi ngokuhlaselwa kukaZihlandlo nguDingane, babaleka bawela uThukela, futhi bayokwakha enhla noMhlathuzana, behambisana nabaMbo nabo ababebalekela ulaka lukaDingane. Kuthe sekuphethe umbuso wamaNgisi, uSomtsewu (Sir Theophilus Shepstone) abantu bakwaNyuswa bakhiswa endaweni entsha enhla neMona eNdwendwe lapho betholakala khona kuze kube namhlanje. Kodwa abakaMgabi babaleka nabo baze bafika ngaseMzimkhulu, sebephethwe yindodana kaNcume uMshiswa. lyona ebusa lamaNyuswa aseZingolweni.Kwathi enye indodana kaNcume enguMkwantshi yona yayokwakha endaweni esibizwa ngokuthi kuseMkhambathini(Camperdown) kanye babakwaBhota(Bothas Hill).Ehlukana kanjalo-ke amaNyuswa,kodwa ebevela ndawonye. Umuzi omkhu lapho kuzalwa khona uSihayo kwathiwa kuseNkumbini.Ngalokho uSihayo wazibiza ngeNkumbemfece. Ukwehlukanisa uNyuswa kaSihayo nabanye oNyuswa, bayaye babizwe ngeNkumbemfece.',
 '["Nsikayesizwe David Junior Ngcobo, South African Rapper", " Kwenzo Ngcobo, Actor"]'),

('zwane',
 'Zwane, Mangethe!\nZikode, Phikelela!\nNtshosho, Nsele kaLindamkhonto!\nNina bakwaVezi!\nMthanti! Gobeni,\nNsele,\nMangethe Zikode kaPhikela,\nWena Wasetsheni,\nUZwane akadlelangaphansi wadlela emkhombeni wezinnyamazane,\nEdla im''hlambi yezinkomo zamadoda,\nNdlangashushwana ngokudla amaNdebele,\nBathi uZwane udleni kwaMtambo?\nKuthiwa udle izinjana ezimbili zigcwele umdakana,\nNtshosho!\nWena kaMafu kawalingani,\nAphansi naphezulu, ngoba aphezulu angubo ngubo,\nNtsele kaLinda kaMkhonto,\nAwungilinde ngilande ezami eZungeni,\nMthanti,\nNduna ngokuthwal'' isila sensele,\nUNtsele kangakanani,\nNgoba nasothini lomkhont'' angahlala.\nIsikhova singathi, “hhi” sibona imihlambi yezinkomo nabantu,\nNin''enadlel''encazeni,\nNin''eniphakel''umyeni odengelani,\nNgoba ningabenkosi.\nZikode kaNdabansele,\nMabhayi kawalingani nawangaphansi nawangaphezulu,\nMangethe,\nNina bakaVezi Owadl''isihlahla njengengwabazane,',
 'Abakwa Zwane abantu baseMangweni (abakwaZwane, Cebekhulu, Linda, Nsele, Hudle nabanye) imvelaphi bangabaseMbo Nguni. Lokho kusho ukuthi badabuka eSwazini njengabo bonke aBambo. Kuthiwa indawo abafike bazinza kuyo kulapho manje sekuzinzile khona inkomponi yaseHlobane. Bagqama kakhulu, ngesikhathi sebepheshwe nguNtshontsho indodana kaMangethe, ngoba uMangethe uqobo lwakhe wayesekhotheme, ekhothemele emzini wakhe eNtshenteka ngasoBivane, endaweni manje esekuthiwa kuseBaqulusini. Kuthe uNtshontsho esabusa kuleyo ndawo wahlaselwa nguShaka. Kuthe ukuba maehlule uShaka wasethatha uNhlaka wakwaMdlalose ukuba abuse kuleya ndawo. Kwathi ukuba aMangwe abone ukuthi indawo yawo isithathiwe okokuphela kubo, bathutha bayokwakha ngaphesheya koMzinyathi. Nalapho baye bahlaselwa babaleka baze bayokwakha namaHlubi. Phela amaHlubi naMangwe babezihlobo. Abantu bakwaZwane manje sesibathola belapha eNdaka ezansi nayo ngaphansi kwentaba uMhlumayo, bakhelenene nesizwe sakwaSithole, kanye nesaMaqamu. Kunezibongo eziningi ezithinta abantu bakwaZwane, aMangwe phela. Kukhona abakwaCebekhulu, kukhona abakwaLinda, kanti kukhona uNsele, uMbambo, uNdiweni, kanye noHudle.',
 '["Lungelihle Uncle Waffles Zwane, DJ", " Themba Zwane, Football Player"]'),

('hlongwane',
 'Ngwane kaNgwadi, Masumpa Masenga sileka Nduku zonobulongwe Nina bakaMatiwane USozisela kaMasumpa noTshani Nina bebutho likaSangweni UZikhali azilingani nezamaxhegwana Sangolibanzi elingawelwa abantukazana Ngoba livalwe ngezihlangu zamadoda Kulobe INtungwa lasenhla kwaSokhumalo',
 'Umlando ngesibongo sakwaHlongwane Abantu bakwaHlongwane ababuye babizwe ngokuthi bangaMangwane bayisizwe eaikhulu kakhulu, futhi esinomlando onothe kakhulu, futhi omude kakhulu. Isibongo sakwaHlongwane sisuselwa egameni lenkosi yaso inkosi uLuhlongwane kaSangolibazi eyabe iphila eminyakeni yama 1200 ngenkathi aMangwane esazinze lapho sekuseSwazini khona namuhla. Yona-ke inkosi uLuhlongwane yazala inkosi uNgwane (okwaqanjwa ngayo isizwe saMangwane), inkosi uNgwane yazala inkosi uMafu, eyazala inkosi uNgunguya, eyazala inkosi uNsele, eyazala inkosi uTshani (uSihayo), eyazala inkosi Masumpa, eyazala inkosi uMatiwane. Inkosi uMatiwane yawunothisa kakhulu umlando waMangwane ngenxa yobuqhawe bayo. Inkosi uMatiwane yabusa ngesikhathi elakwaZulu libuswa iSilo uShaka kaSenzangakhona. Ngaleso sikhathi isizwe saMangwane sasizinze lapho sekuseMnambithi khona namuhla. Kukhona nendawo yaseMatiwane khona eMnambithi eyaqanjwa ngayo inkosi yesizwe saMangwane. Kukhona futhi nentatshana iMatiwaneskop khona futhi kuleyo ndawo. Ekubuseni kwayo inkosi uMatiwane yadala omkhulu kakhulu umonakalo ezizweni eyame yakhelene nazo. Yazihlasela, ezinye zazo yabulala namakhosi azo, njengengaseMahlutshini yabulala inkosi uMthimkhulu kaBhungane, eMazizini yabulala inkosi uDweba. Yaqhubeka yahlesela noMpangazitha umnawakhe wenkosi uMthimkhulu kodwa yena ayizange imbulale, waphulukundlela wabeleka. Nenkosana yakhe uMehlomakhulu kaMpangazitha naye wabaleka wabheka enyakatho, wayokhonza enkosini yabakwaKhumalo uMzilikazi eyabe izinze eMosega. Nakhona uMehlomakhulu akahlalanga isikhathi eside kuleyo ndawo, wagcina ebheke eKoloni nokuyilapho agcina ekhothamele khona. Ngemuva kokubulawa kwenkosi uMthimkhulu ibulawa yimpi yenkosi uMatiwane isizwe saMahlubi ahlakazeka, iningi laso layokhonza eSilweni uShaka. Kuyilapho-ke iSilo uShaka sabutha khona ibutho leZiyendane zikaNandi nokulibutho elalande izinsizwa zaseMahlutshini. Laqala lapho-ke iLembe ukuhlasela aMangwane, kuyizinsizwa zaseMahlutshini zeZiyendane ezaziyisifuba sempi yeLembe ngenhloso yokuziphindiselela ngobulawa kwenkosi uMthimkhulu kaBhungane. Inkosi uMatiwane yagcina ibalekile yaqonda eLesotho kumngane wayo inkosi uMushweshwe. Kodwa ayizange ihlale isikhathi eside kwelikaMushweshwe, yabuye yabhekisa amabombo eKoloni, yazinza lapho sekuyidolobha laseButterworth namuhla (EMbolompo). Inhlalo yizange ibe yinhle eKoloni ngoba amaNgisi ayesevele esilidle lonke elaseKoloni, iKumkani uHinsa kaKhawutha yayisibusela wona amaNgisi, isiyinkosi ngegama nje. Ngakho-ke amaNgisi ayimisa kabi impela inkosi yaMangwane ngoba kwakufana nje nokuthi isezweni lawo, futhi amaNgisi ayesezwile ngobungozi nangobughawe manje. Ngakho-ke ahlela indlela yokuyihlasela. Ngempela aqoqa zonke izizwe ezinsundu ukuba ziwelekelele ekulweni nenkosi yaMangwane. Kulezo zizwe singabala esaBathembu nesaMaGcaleka eKumkani uHinsa. AmaNgisi wona ayeholwa ngoDundas noSomerset empeleni abangazange balwe nhlobo kepha bahlomisa izizwe ezinsundu ngezinduku zamagwala bona bangenza lutho, babuka zingikilana. Ngempela yahlaselwa inkosi yaMangwane, ukughuma kwezibhamu kwadla umunyu empini yaMangwane eyabe yethembele ezihkangwini, ingenazo izibhamu. Yanqotshwa impi yenkosi uMatiwane, kwakungunyaka wezi 1828 nokuwunyaka iLembe labulawa ngawo. Inkosi uMatiwane yaphoweka ukuba ibuyele kwaZulu. Ngaleso sikhathi kwasebusa iSilo saseMgungundlovu iSilo uDingane, esafike sayibulala inkosi yaMangwane. Indlalifa yenkosi uMatiwane kwakunguZikhali owasebuthweni uMkhulutshane. Waghubeka ekulelo butho kwaze kwaba isikhathi sempi yaseNcome lapho alwa khona ngobuqhawe. Kwathi ngemuva kwaleyo mpi uZikhali wafudukela eSwazini nedlanzana labalandeli bakhe. Wafika waganwa indodakazi yeNgwenyama uSobhuza uNomlalazi eyamzalela indlalifa yakhe uNcwadi, uNyanda nabanye. Zazikhona kodwa ezinye izingane zeNkosi uZikhali ngoba yayiganwe ngamakhosikazi amaningi kakhulu. Kwathi uZikhali esahleli eSwazini kukuhle kuyinqaba walunywa indlebe nguNomlalazi ukuthi iSilo uSobhuza sasihlela ukumbulala. Akabange esacitha sikhathi uZikhali wahamba nabalandeli bakhe waphindela kwaZulu. UNcwadi wazala uSwanalibomvu, uBambazi nabanye. USwanalibomvu wazala uNgwabazi. Enye yamadodana enkosi uMasumpa yasekhohlo uMphayise yazala uMzamo okwavela ngaye isibongo sakwaMzamo',
 '["Bongokuhle Hlongwane, Football Player ", " Thomas Hlongwane, South African Football Player"]'),

('mkhwanazi',
 'Veyane kaCungethe Mtubatuba Wena owalobolela amadoda Ndonga, Shamase, Mayanda, Nkwali yenkosi Dlebhu wabeSwazi Somkhele',
 'Abantu bakwaMkhwanazi imvelaphi yabo isenhla nezwe njengabo bonke abaNguni. Ngokwezigaba zabaNguni bona bangaMalala Nguni. Ngenkathi befika kwelakwaZulu babekade beqhamuke eSwazini. Ngaleso sikhathi elakwaZulu kwakusengelalwaMthethwa. Kwakubusa inkosi uKhayi nokuyiyona eyakha ubukhulu budlelwano noMdolomba okunguyena owayehola abaKhwanazi ngenkathi befika kwaMthethwa. AbaKhwanazi eSwazini babekade beyindlenye yabakwaShiba. Ngenkathi befika kuleli osekungelakwaZulu abaKhwanazi babengamaqembu amathathu. Kwakukhona iqembu likaMdolomba elakhonza enkosi uKhayi, kukhona iqembu elaliholwa nguMnyenyeza nokuliqembu elaziwa manje ngokuthi lingaBakhwanazi bakwaMnqobokazi. Bese kuba khona iqembu elaliholwa nguMdima elaziwa ngokuthi ngaBakhwanazi bakwaDlangezwa. ElikaMnyenyeza lakha phakathi kwemifula iHluhluwe neNyalazi eduze nesizwe saseMncwangeni. ElikaMdima lona lakhelana nabakwaMsane. UMdolomba (hhayi owakwaMyeni) wazala uCungele owazala uVilana owazala uMayanda owazala uSomkhele owazala uMtubatuba owazala uMgwazeni owazala uMinus. Ulibo lwamakhosi akwaMkhwanazi lolu. Inkosi uVelana kaCungele yaba ngezinye zezinsika zomuzi wenkosi uDingiswayo owawubuzwa ngokuthi kusoHheni. Okwathi ngemuva kwesikhathi yaba yinduna yasoHheni. Ngokuthi yake yaba yinsila yenkosi, kwabe sekuthiwa abantu bakwaMkhwanazi bangoNkali yenkosi, behlonipha insila yenkosi. Inkosi uVelana yazala inkosi uMayanda eyaganiselwa iSilo uMpande udadewabo uNtiliki ozale uSomkhele uyise wenkosi uMtubatuba. Umuzi wenkosi uVelana owawubizwa ngokuthi kukwaMpukunyoni, wawakhelwe lapho sekulidoloha laseMtubatuba, nalo elaqanjwa ngenkosi.',
 '["Nhlanhla Mkhwanazi, Provincial Police Commissioner"]'),

('mkhize',
 'Gwabe, Khabazela kaMavovo kaZihlandla, Gubhela, Mumbo omhlophe, Wena waseMbo, Wena okhanya amasi esiswini, Singela, Nhlama eyaphelel''etsheni, Ngunezi, Mumbo ombulazi, Nina enadla umuntu nimyenga ngendaba, Sibi side esimajembelezana, Sibi side esimaphandla esaphandl''abeNguni bavungama, Nina bengwazemabhudle, Eth''isabhudla yabuye yaphinda yabhudla, Malala amahle, Nin''enalala nomunwe endunu, Navuka nakhwif''ilanga, Nzalo kaSambela, Nina bakaSidaphudaphu ngokubadaphunela, Nzalo kaLuzalo!',
 'Abantu bakwaMkhize kuthiwa ngabeseMbo ngoba beqhamuka kuMumbo, uyise kaZalankomo, uZalankomo yena wazala uLanga. Futhi bengaBaMbo Nguni. Nabo futhi bayazalana noDlamini baseMbo kanye noNdwandwe. Kuthathwe eside isikhathi ukuba babhajadiswe ngesibongo sakwaMkhize, sonke lesi sikhathi bebaziwa ngokuthi ngabaseMbo. Abantu bakwaMkhize kuthiwa kwathi uma behlukana nabanye bona batholwa ngaMaputukezi eTalagubhe. Kuthe emva kwalokho basuka bagudla ulwandle ngaseMpumalanga, behla njalo benbheke ngaseNingizimu, baze bafika eChwebeni (St Lucia Bay). Njengabantu abafuye kakhulu babethanda ukuthi imfuyo yabo iklabe lapho kunamazolo khona. Kodwa amazolo ayezotholakala kanjani eduze nolwandle? Kwaba kubantu baseMbo ukuthi bafune indawo engcono. Ngakho bahamba ezindaweni eziphakeme ezihlala njalo zinemikhizo. Kuthiwa bahamba njalo baze bayofika ezintabeni zaseQhudeni. Ngenxa yokuthi laba bantu banbehamba ezindaweni ezinemikhizo, kwase kuthiwa ngabakwaMkhize. Bafika laphaya eQhudeni sebeke bazinza emahlathini aseNgome. Laphaya eQhudeni bakha kusuka ehlathini laseQhudeni kuze kuyofika emfuleni iNsuze, kanti ngaseNtshonalanga bavinjwa uThukela, kwathi ngaseNyakatho bavinjwa nguMzinyathi. Inhloko yabo ngaleso sikhathi kwakunguMavovo indodana kaGubhela. Izizwe ababakhelane nazo ngezaseBathenjini, kanye naMachunu. Kwathi ngesikhathi kubusa uShaka kwaZulu, kwaMkhize kwakubusa uZihlandlo indodana kaGwabe. Kwathi ukuba uZihlandlo abone omakhelwane bakhe abanamandla kakhulu kunaye bebhuqwabhuqwa nguShaka, baze banyamalala phambi kwakhe, futhi kuyizizwe ezinamandla, wavele wenza ubuhlakani bokuphephisa isizwe sakwaMkhize olakeni lukaShaka ngokuba ayozinikela kuye, wazakhela obukhulu ubuhlobo, okwaze kwaduka iLembe bengabangani. Kuthiwa uZihlandlo wayesavakashela njalo inkosi yakhe uShaka, esuka emzini wakhe kwaNyakenye ngaphesheya koThukela. Kuthiwa nguyena muntu wokugala owabona umuntu omhlophe. Bathi wayethi yena yishaywa (laba bantu abamhlophe). Kanti ngumlungu (u-Isaacs). Wamthatha wamusa emzini wakhe. Akakhohlwa u-Isaacs emibikweni yakhe indlela abantu bakwaMkhize nenkosi yabo abelunge ngayo nangendlela abahlonipha ngayo. Kuthiwa ngendlela ayemthanda ngayo uZihlandlo uShaka kwaze kwambangela isigwagqwa kubafowabo bakaShaka nasezinduneni zakhe. Yingakho uDingane wathi uma ethatha ubukhosi wazama ngayo yonke indlela ukuba asuse phambi kwakhe bonke ababeyizihlobo nabangani bakaShaka. Omunye owayesohleli lukaDingane kwakungaba ngubani ngaphandle kukaZihlandlo wakwaMkhize, owayakhe umuzi wakhe eQhudeni obizwa ngokuthi kukwaDimane. Kuthiwa uDingane wathumela abantu ukuba bayothi kuZihlandlo akalethe yena nabantu bakhe iminyaba yezintungo ukuba kuzokwakhiwa umuzi waseMgungundlovu. Ngenxa yokuthi abantu bakwaMkhize babakhe eduze nehlathi kabakushayanga mkhuba lokhu. Kodwa bengakazigawuli izintungo, kwafika izithunywa zikaDingane zilethe umyalezo oyimfihlo kuZihlandlo. Kwathi engazelele, bamgwaza ngomkhonto wafela khona lapho. Kubantu baseMbo akekho umuntu owaba nesihluku njengoDingane. Ngokubona lokhu, kwafanela ukuba abantu baseMbo bathi ''nyawo zami ngibelethe''. Indodana kaZihlandlo, uSiyengela, wayesemncane ekubeni angahola abantu bakwaMkhize, benjalo bebakeka. Nakho uMsengi, indodana kaSambela umfowabo kaZihlandlo, yena wayeseqinile, ngakho wathwala lo mthwalo wokuhola abantu bakubo. Bathi wayehamba nemindeni engamakhulu amathathu kuya kwamane. Kwabuye kwathelela abahlobo babo bakwaNdlovu ababeholwa nguMpongo indodana kaZingelwayo kaLamula kaNgema, bahambisa bayofuna amadlelo aluhlaza. Kuthiwa bahamba baze bayofika phakathi komfula uMkhomazi kanye neLovu. Base bekhathele, ngakho-ke bahlala lapho kuze kube namanje le ndawo isabizwa ngokuthi kuseMbo. Kwabusa uSiyengela ngoba uMsengi wayesewuqedile umsebenzi wakhe naye esezifunela amadlelo aluhlaza kwelingafulwa nkonyane. Yena (uMsengi) benoMpongo nethimba labo bahamba bayokwakha eMngeni, ngaseNhlazuka. USiyengela wakha umuzi noma isgodlo sakhe wasibiza ngokuthi kusesiMahleni. Ekukhothameni kwakhe, kwabusa indodana yakhe uNgunezi owaganwa yinkosazana kaMswati indodana kaSobhuza wokuqala. Nizokhumbula ukuthi ngithe abaseMbo nabakwaNgwane (Dlamini waseMbo) bayazalana. Kodwa uNgunezi wabe esebuqeda ubuhlobo. Kule nkosazana yaseSwazini wazala uTilingo owamiswa ukuba abe yinkosi ngumbuso waseNatali ngoba kuthiwa wasizana noBhambatha.',
 '["Shauwn Mkhize, South African Socialite", " Saul Vusumzi Mkhize, South African human rights activist"]'),

('dlomo',
 'Mkhabela, Dinangwe, Bhelesi, Khweba, Sikhaba esingangenkomo',
 'Abantu bakwaDlomo bangaMalala Nguni ngokwezigaba zabaNguni. Phela abaNguni bahlukaniswe izigaba ezinhlanu: abaMbo Nguni, abaNtungwa Nguni, aMalala noma amaHlenga Nguni, amaDebe Nguni kanye nabaThonga Nguni. Bonke abaNguni baqhamuka enhla nezwe. Ngenkathi befika, abakwaDlomo beqhamuka khona enhla nezwe bafikela eHlathini likaDlamini eduze naseGreytown. Laba bantu bakwaDlomo babuye baziwe ngokuthi bangaMakhabela kususelwa egameni likaKhokho wabo uMkhabela indodana kaDinangwe kaDlomo. Ngakho-ke umuntu onguyena nzalabantu yalesi sizwe saMakhabela nguye uDlomo uqobo lwakhe. Zonke izindlu zaMakhabela zihlangana kuDinangwe kanti futhi nguyena muntu abamazisa kakhulu abantu bakwaDlomo uma bethakazela. Endlunkulu uDinangwe wazala uJongo owazala uMkhulu owazala uKhopho noFabase. UKhopho wazala uMagedama owabe esemncane kakhulu ngenkathi iNgonyama Shaka ihlanganisa izizwe kusukela ngowe 1818 kuze kube ngowe 1828. Endlini yaseKhohlo wazala izintombi zodwa. KweyeQadi khona wazala uMkhabela owazala uBhelesi owazala uKhweba owazala uPhini owazala uMqabuli owazala uMkhandi owazala uMgewula owazala uZweni ozala uMthokozisi nokunguyena oqoqe lo mlando waMakhabela. Indawo abasazinze kuyo manje abantu baseMakhabeleni inamahlathi amaningi aminyene kakhulu kuze kube namuhla. Ngenkathi iSilo uDlungwane kaNdaba sihlanganisa izizwe, abantu baseMakhabeleni babebuswa inkosi uFabase eyabe ibusa njengebambabukhosi, ibambele uMagedama (inkosana yomfowabo) owabe esakhula. Kwangelula kokaNdaba ukuba ahlasele aMakhabela ngenxa yamahlathi ababakhe kuwo. Kuthiwa kwakuthi lapho bebona impi yeLembe izobahlasela babaleke bayongena ehlathini. Lelo hlathi lagcina lifaniswe nenqaba yabo. Kwakuthi nxa sebengene kulelo hlathi bazihlukanise bangahlali ngamaqoqo, kodwa babesakazela nalo ihlathi lonke bahambe ngababili noma ngayedwana. KwaZulu impi yayingabahlaseli abantu ababehamba ngababili noma ngayedwana. Isu labo lokuzihlukanisa labasebenzela kahle kakhulu ngoba labaphephisa ezimpini zeLembe kwaze kwafika isikhathi sokukhothama kwalo. Kwaze kwakheka nesaga esithi ''kanti ngumuntu munye yini njengakwaFabase?''. Kwathi lapho sekufanele ukuthi inkosi uFabase ishenxe esikhundleni idedele uMagedama, yanqwaha nesikhundla sobukhosi. Ngesizathu sokuthi uMagedama wabe enabalandeli abaningi abadlula abakaYise omncane uFabase, uFabase wagcina ephoqeka ukuba aqembuke nedlazana labalandeli bakhe ngasemfudlaneni iHlimbithwa wayoziqalela ubukhosi bakhe phansi. Nabuya ubukhosi bakhe eMvoti. Babuyela kanjalo-ke ubukhosi baseNdlunkulu yaMakhabela kuMagedama. UFabase eMvoti wazala indlalifa yakhe uMngcangca owazala uKutula. Ebukhosini baseNdlunkulu uMagedama wazala uGayede owazala uMkhuzangwe. Okunye esingakuphawula ngaMakhabela wukuthi abantu bakwaDlomo abatholakala kwaBulawayo eZimbabwe akubona abaseMakhabeleni, bangaseMahlutshini. Baphuma esendeni likaDlomo wokuqala ozalwa nguHadebe wesibili owayezalwa nguMthimkhulu wokuqala. ODlomo baseZimbabwe uma bethakazela bathi ''Hadebe, Bhungane, Shwabada, Xaba, Mashiya, Langalibalele'' njalo-njalo. Abanamthinti nhlobo noDinangwe noma uMkhabela. Okunye futhi esingakuphawula mayelana naMakhabela wukuthi abakwaMkhabela abaseMpumalanga koMbombela bangaMakhabela impela akanye naMakhabela akwaZulu.',
 '["Sizwe Dhlomo, Radio host", " Albert Dlomo, Political activist"]'),

('ngubane',
 'Mbovu, Somahhashi, Nyoniyezwe, Nomafu, Myaluza, Ngcukumane, Zikode elimhlophe, Matomela, Nzombane, Ngogozabantu, Nomasikisiki, nyon''esindwa isisila sayo, Ndoda kaNyamazane, KaSodlelezi esadl''amabele amhlophe sawashiya nenkehlane, Ngcingcw''ephuza kwezid''iziziba, Uma ingaphuza kwezimfushane umlomo ungabuya nodaka, Vathu oluphezulu ngoba oluphansi olwabafokazane, Nina baseMabovini okwakhala inkomo kwakhala imbuzi kwasha imizi, Nomaphikwane!',
 'Abantu bakwaNgubane bangabaNguni bohlobo lwaMathonga Nguni ngokwezigaba zabaNguni. Lesi sibongo sakwaNgubane siphuma kwesakwaMkhize, inkosi uSibiside eyadabula abantu abakwaNgubane. AbakwaMkhize bona bangabaNguni bohlobo lwabaMbo Nguni, noma ngithi abaNguni baseMbo. Isibongo sakwaNgubane singesinye sezibongo ezaqambeka ngegama lomuntu. UNgubane lona oqanjwa ngaye isibongo wayeyindodana kaNgogozabafo kaMyaluza kaNgcukumane kaNgwane kaNomafu. NguNomafu-ke owabe eyindodana yenkosi uSibide. UNomafu wayengumfowabo Shange owazala abakaShange. Enye indodana yenkosi uSibiside kwakunguNjanya owazala aMampondo enkosi uFaku. UNjanya nguyena futhi owazala aMabomvana, Gambushe nabakwaChonco. Zonke lezi zibongo zihlobene ngokwegazi kodwa manje seziyaganiselana. Abantu bakwaNgubane sibathola bakhe eQhudeni bengomakhelwane woZuma, Mkhize, Mchunu, Mthembu nabanye. Kodwa kwahamba kwahamba laba bantu bakwaNgubane bathi cithi saka kulo lonke elakwaMthaniya, koMsinga, koSwayimane, koMooi River nakwezinye izindawo. Laba bantu ngesikhathi seLembe babezihlalele kamnandi benethezekile ngaphansi kwenkosi yabo uNzombane kaNdlovu. Inkosi uNzombane yayiyingumfowabo Matomela. Babebabili oMatomela futhi ngesikhathi esisodwa, kwakukhona owakwaZuma kanye nowakwaNgubane. Abantu bakwaNgubane kanye nabakwaZuma emandulo babengabahlobo nje, kwakungekho ukuhlobana. Izinto zashintsha ngesikhathi sokubusa kweSilo uDingana sona esahlasela bonke abantu ababengabahlobo beLembe. AbakwaNgubane nabo bahlaseleka kanye nabahlobo babo abakwaZuma kanye nabakwaMkhize. Inkosi uZinhlandlo Mkhize yakhothama ngesikhathi salowo mkhankaso weSilo uDingane wokuhlasela bonke ababengabangane beLembe. Umuntu owagqama kakhulu emlandwini wakwaNgubane ize wagqama kabi inkosi uSobhuza (uSobuzwe) eyayibuye yaziwe ngelikaSibindi. Inkosi uSobhuza yayizalwa yinkosi uNzombane kaNdlovu. Yona-ke yagqama ngokulwa ngasohlangothini IwaMaNgisi eSandlwana. IsiZulu sithi ''inkonyane yomgakla yega lapho kwege khona unina''. Inkosi uSobhuza yazala inkosi uNjengabantu eyaqhubeka lapho kwakugcine khona uyise ngokuba yisandla saMangisi ekuhlukumezeni ingabade.',
 '["Menzi Ngubane, Actor", " Dr Harriet Ngubane, Scholar"]'),

('ngema',
 'Mngadi, Madlokovu, Ntusi yenkomo, Nene, Wena nasentendeni yesandla uyanela, Muji, Nina baseNgweni, Sthenjwa, Madlokov''esengweni, Sabel''uyabizwa eNkonjeni ubizwa abamhlophe ukuzokhuluma ngomhlabathi wakini kaMalandela, Sthuli saseNgweni!',
 'Abantu bakwaNgema bangabaNguni abawuhlobo wabaNtungwa Nguni ngokwezigaba zabaNguni. Laba bantu bakwaNgema babuye baziwe ngokuthi bangabaseMangadini. Kanti futhi laba bantu kusengabantu bakwaNene. Badume ngezithakazelo zabo oMadlokovu, Ntusi yenkomo, Sithenjwa nezinye. Laba bantu baseMangadini bahlobene kakhulu nabantu bakwaZulu nabakwaQwabe. Lesi sibongo sakwaNgema saqambeka ngaye uNgema. UNgema wayeyindodana kaNtusi kaMafu. Laba bantu babekade bekanye nabakaMalandela, uMalandela esimthola akhe ngasegqumeni iMandawe, umuzi wakhe wawubizwa ngokuthi kusoDwini. Kodwa uMalandela akahlalanga lapho isikhathi eside ngoba wabuye wafuduka wawelabuMhlathuze wenyukela ezintabeni zaseNkwenkwe. Waqhubeka wawela umfula owaziwa ngokuthi kuseMfule uma wedlula kanxane edolobheni laseMalimade. Ngenkathi uMalandela nabantu bakhe befika ngasemfuleni uMfule bawfica ungenisa. Ingxenye yabantu bakaMalandela naye uqobo yasheshe yawela umfula ungakagcwali, kwathi enye ingxenye yangawela, yailibalela ngokuzindlela izitshalo zabantu bakwaXulu ezazibizwa ngokuthi ''izingadi noma amangadi''. Kuleyo ngexenye eyalibala ngokudla izingadi kwakukhona noNgema okwagcina kuqanjwe ngaye isibongo sakwaNgema. Umfula wagcina ugenise wagcwala, bagcina besale nganeno laba abalibala ukudla izingadi. Kwathi labo ababekanye noMalandela baqhubeka nohambo bagcina bezinze ngasemfuleni iMpembeni. Ngesizathu sokuthi uNgema nabantu bakhe basala bezilibalele izingadi, bagcina bezithole isibongo esisha noma igama elisha kwathiwa bangabaseMangadini. Nomholi wabo uNgema wathola igama elisha, kwathiwa unguMngadi. Namanje isizukulwane sakhe sibizwa ngokuthi singesakwaNgema, abanye babo bona bakhetha ukusebenzisa uMngadi njengesibongo. Basala-ke eMfule ezweni lakwaXulu bakha amadlangala. Sakhula isizwe sakwaNgema sagcina sisabalele izwe lonke. Laba bantu bakwaNgema babuye baziwe ngokuthi bangabaseNgweni kuselwa egameni lomfula lapho kwatshalwa khona inkosi yabo uMadlokovu kaMlaba laphaya eThemba kwaNomponjwana. UNgema noma uMngadi wazala inkosana yakhe uYabana owagcina ethuthile wayokwakha ezansi komfula uMfule ngaseMakhasaneni ngaphesheya kwesigodi sakwaBhadaza (Planti). Kuze kube namuhla leya ndawo afikela kuyo yaziwa ngokuthi kukwaYabana. Abantu bakwaNgema bagcina sebehlakazekile — abanye banyukela eNdundulu, abanye babuyela emanxiweni kaMalandela. Umuntu esimbona egqama kakhulu emlandwini wabantu baseMangadini nguSigwelegwele kaMahlekehle, iqhawe elahlabana kakhulu eSandlwana lapho uZulu azidlela amahlanga kuMaNgisi ngowe-1879 kuMasingana. USigwelegwele wayeyinduna yebutho leNgobamakhosi, nokuyibutho elambandakanya uMehlokazulu kaSihayo Ngobese naye owahlabana kakhulu eSandlwana. Kukhona mando ongelona iqiniso othi uSigwelegwele nguyena owaqala umkhuba wokusoma. Akulona iqiniso lelo ngoba ziningi izibongo ezakheka ngomkhuba wokusoma futhi ezakheka engakazalwa nokuzalwa uSigwelegwele. Kulezo zibongo singabala esakwaMdlalose esaphuma kwesakwaZulu, esakwaMdletshe esaphuma kwesakwaMthethwa, esakwaNyandeni esaphuma kwesakwaKhumalo nezinye. Ukusoma — ukwenza ucansi lapho owesilisa ephelela emathangeni entombi, engafiki enkomeni kaBaba.',
 '["Mbongeni Ngema, Playwright", " General Nhlanhla Lucky Job Ngema, the first black South African to qualify as a licensed air transport pilot."]'),

('zuma',
 'Nxamalala, Mndlovu, Mafahleni, Nina bakaLugaju kaMatomela kaShisa. Mashingizela ashiye impi yakhe, Dwala elibushelelezi. Maphum''phethe inyama ngala, amasi ngapha, nobukhosi namasi ngapha, nobukhosi.',
 'Imvelaphi yabantu bakwaZuma ingabeSuthu, aBatlokwa. Baliqhamukisa eLisuthu banqamula ezintabeni zoKhahlamba behla njalo baze bafika eThukela. Ekuluweleni kwabo baficana nesizwe saseMadekeni esasibuswa nguMnikadi. AMadeke abafundisa ukutshalwa kommbila — into bona ababeyeshwama. Isisho sesiZulu sithi ''umbeki weNkosi uzithela isisila akabusi nayo.'' Abantu baseMadekeni bafundisa abantu bakwaZuma ukutshala ummbila, babafundisa nokuthi udliwa kanjani, kodwa bona kabadlanga ummbila kuphela — base bedla nezwe laMadeke. Izwe elasala ladliwa nalo futhi ngaMakhabela. Kuthe besazihlalele benethezekile abantu bakwaZuma kwafika impi yeLembe eyayishakazisa lonke izwe. Kwathi inkosi eyayibusa amaNxamalala (abakwaZuma) ngaleso sikhathi, uMatomela, yanikela ngendodana yayo kanye nezinye izinsizwa ukuba ziyoba ngamabutho kaShaka. Indodana yakhe kwakunguSiguqa noma uSondaba. Kodwa uSiguqa wabuye wabulawa ukufa, akabe esaqhubeka nokuba yibutho likaShaka. Owagcina eyindlalifa kwaba nguMsholozi kodwa ngokubambela umnawabo kaSiguqa, uLugaju. Ngokwenza kukaMatomela ukuba azinikele kuShaka, kwenza ukuba abantu bakwaZuma bangathinteki lapho babakhe khona. Kodwa kwathi ukuba kukhothame iLembe, uDingane wafuna ukushabalalisa zonke izihlobo nabangani bakaShaka. UMsholozi wezwa ukuthi umakhelwane wakhe uZihlandlo waseMbo (wakwaMkhize) ubulewe nguDingane, kwathi emva kokuxoxisana nezikhulu zakwaZuma, babona ukuthi ''isigwaca esihle ngesishoshayo.'' Basuka abantu bakaMsholozi endaweni yakubo ngaphezu koThukela, babaleka. Kuthe bengakafiki endaweni okuthiwa manje nguMgungundlovu, bazithela empini yakwaZulu eyayibabalindela. Phela uMbombosh''omnyama (uDingane) wayenamehlo nezindlebe ayesewabeke kulo lonke izwe. Eduze kwabantu bakwaZuma kwakukhona uSotobe kaMangalala (wakwaSibiya) owayakhe eduze komfula iNadi, owayehlezi ebeke iso nendlebe ukuthola ukuthi abantu bakwaZuma benzani. Nguyena owazisa uDingane ukuthi uMsholozi nabantu bakhe sebelishiya elengabadi. Yikho-ke uDingane wathumela amabutho akhe ukuba ayovimba. Umphumela walokhu kwaba ukufa kukaMsholozi. Abantu bakhe babuyela emuva begqutshwa okwezimvu. Kodwa kwathi kungazelele muntu, uLugaju, owayengaphathekile kahle ngokuhlala ngaphansi kombuso kaDingane, wanyamalala nabanye abantu bakwaZuma. Uze watholakala ngaseMgungundlovu. Endaweni manje esibizwa ngokuthi kukwaNxamalala, sebengaphansi kwendodana kaLugaju, uMafahleni. Indlu kaMsholozi yona yedlulela eMpendle, isiholwa nguMnyakanya kaMsholozi owazala uNdukuyakhe. Ukwelamana kwaMaNxamalala: uZuma wazala uDzama, yena wazala uMaphuma nabanye. UMaphuma wazala uZitho owazala uMndlovu nabanye. UMndlovu wazala uMgebhe owazala uShisa nabanye. UShisa yena wazala uMatomela nabanye. UMatomela wazala uMsholozi, uSiguqa kanye noLugaju. ULugaju wazala uMafahleni. Kwathi uMsholozi yena wazala uMnyakanya owazala uNdukuyakhe.',
 '["Jacob Zuma, Former President"]'),

('majozi',
 'Mgamu,Mabelemade wena owancelisa ingane ngaphesheya komfula, Gwanyana, Mbhuli, Mabhulangwe wena owabhula izingwe wabhula izingonyama, Ngoza Lukhozi, Maphiliphili mbheka phansi onjengesambane!',
 'n/a',
 '["Simphiwe Majozi - Actor/ Singer"]'),
 
 (
    'cele',
    'Ndosi, Magaye, Nkomo isengwa ilele Nkomo kayivuswa, Khumbuza, Siqunga esihle esingahlalwa nyoni. Mkhokheli owakhokhela isizwe ekugqilazweni. Dubandlela, Magaye ongangolwandle.',
    'Abantu bakwaCele bangaMalala Nguni ngokwezigaba zabaNguni. Lesi sibongo sakwaCele siphuma kwesakwaMthethwa. Ukhokho wabantu bakwaCele nguMadango kaNdunakazi kaMthethwa kaNyambose kaKhubazi. UMadango endlunkulu wazala uXaba owazala uKhayi owazala uJobe owazala uGodongwana (inkosi uDingiswayo). Ekhohlo uMadango wazala uCele owazala uLugogo owazala uNdosi owazala uMaganga owazala unqumela owazala uLanga owazala uMkhokheli owazala uDubandlela. Inkosi uDubandlela yayakhe umuzi wayo endaweni osekuyi Groutville manje. Ngesikhathi sokubusa kwenkosi uDingiswayo kwaMthethwa kwaCele kwakubusa yona inkosi uDubandlela. Inkosi uDubandlela yaphila isikhathi eside ngendlela eyisimanga angangokuthi amadodana ayo okwakufanele athathe ubukhosi emva kwayo aze ashona kwawona. Endala kwakunguMdinsilwa owashona nendodana yakhe bengabusanga. Encane kaakunguVico, naye washona uyise esawadla anhlamvana. Kwase kuthi amadodana kaVico, oMande noMagaye, bathathelana izikhali babanga ubukhosi uyisemkhulu esaphila. Ekubangeni kwabazukulu benkosi uDubandlela nguMagaye owadla umhlanganiso. UMagaye washiya emzini kayisemkhulu wayokwakha umuzi wakhe emthonjeni womfula uMhlali, kwathi umfowabo uMande wawela umfula uMvoti wazokwakha lapho sekuyidolobha lakwaDukuza khona. \n Kwathi lezi zinsizwa zisazihlalele emizini yazo wafika izithunywa zivela eSilweni uShaka, saqale saya kuMande, sathi, ithi iNgonyama impi yayo ilambile ifuna ukuba ithole ukudla ukuze ithole amandla okulwa. UMande wakhomba inja endala ezacile wathi kabathathe yona bayokudla. Lezo zithunywa zedlulela kuMagaye zafika zasho umlayezo ofanayo, yena waziphatha kahle wazihlabisa nokuzihlabisa,wethembisa nokuthi uzozinekeza konke ezikufunayo. ILembe layizwa indelelo kaMande lathukuthela lathelwa ngamanzi. UMande wafunda kwezakhe washeshe wabaleka nabantu bakhe bashiya yonke imfuyo yabo esitheni. Babaleka bayocasha ngasolwandle. ILembe lathi makangalandelwa kodwa makancishwe ukudla. Yabhoka indlala kangangokuthi uMande waze wacela umfowabo uMagaye owayehlezi ngokunethezeka neSilo uShaka ukuba makayomncengela kuso. Ngempela uMagaye wamncengela umfwabo eNgonyameni yakwaZulu. Yavuma yathi makaphume ekubhaceni abuyele emzini wakhe. Kwathu lapho esazihlalele enethezekile zaphinde zaqhumuka futhi leziya zithunywa zeLembe. Kulokhu zafike zathi ithi iNgonyama sizobamba leya nja ezacile siyibulala sidle. Ngempela zazizobika ukuthi uMande makazilungiselele impi ngoba wayezohlaselwa kungekudala. Wafunda kwezakhe futhi uMande wabaleka, wavele wanyamalala. Kwase kuthi iLembe lavele lazikhokhisela ngokuthi livele lakhe umuzi walo wakwa Dukza emanxiweni kaMande. Lowo muzi yiwo osulidolobha manje. Kwathi lapho iSilo uShaka sesikhotheme sekubuza iSilo uDingane, iSilo uDingana saqala umkhankaso waso wokubulala bonke ababengabangane beLembe. UMagaye naye wabulawa. Esekhotheme uMgengi sekubusa iSilo uDingane waqhamuka futhi uMande. Kuthe lapho esahleli ejabulele nanokuthi isitha sakhe asisekho kwaqhamuka uNqetho Qwabe wahlasela uMande. Bahlakazeka abantu bakwaCele bagcwala lonke elakwaZulu.',
    '["Amahle Cele, South African Artist", " Henry Cele, Football Player & Actor", " Baby Cele, Actor"]', '["public/images/Baby_Cele.jpeg", "public/images/Henry_Cele_1986.png", "public/images/Willard-Cele-1951.jpeg"]'

);

